window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[223]={"id":"223","numero":223,"titre":"Dyslipidémies de l'adulte et de l'enfant","objectifs":[{"id":"223-1","rang":"A","rubrique":"Définition","titre":"Connaître l’évaluation du risque cardiovasculaire global","contenu":"<p>L'<span class=\"kw-def\">évaluation du risque cardiovasculaire (RCV) global</span> est le <strong>préalable obligatoire</strong> à toute décision thérapeutique sur les lipides : c'est elle qui fixe l'<span class=\"kw-bio\">objectif de LDL-cholestérol</span> à atteindre et le seuil de mise sous traitement <span class=\"kw-etio\">médicamenteux</span>.</p>\n      <p>On distingue <strong>cinq catégories de risque</strong> : <span class=\"kw-def\">faible</span>, <span class=\"kw-def\">modéré</span>, <span class=\"kw-def\">élevé</span>, <span class=\"kw-def\">très élevé</span> et la <span class=\"kw-def\">prévention secondaire</span> (patient ayant déjà fait un événement <span class=\"kw-etio\">athéromateux</span>).</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie de risque</th><th>Objectif <span class=\"kw-bio\">LDL</span>-c</th><th>Conseils mode de vie<br>(+ traitement si non contrôlé)</th><th>Mode de vie + traitement d'emblée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Faible</strong></td><td><span class=\"kw-chiffre\">&lt; 1,16 g/L</span></td><td><span class=\"kw-chiffre\">1,15 – 1,9 g/L</span></td><td><span class=\"kw-chiffre\">≥ 1,9 g/L</span></td></tr>\n          <tr><td><strong>Modéré</strong></td><td><span class=\"kw-chiffre\">&lt; 1 g/L</span></td><td><span class=\"kw-chiffre\">1 – 1,9 g/L</span></td><td><span class=\"kw-chiffre\">≥ 1,9 g/L</span></td></tr>\n          <tr><td><strong>Élevé</strong></td><td><span class=\"kw-chiffre\">&lt; 0,7 g/L</span></td><td><span class=\"kw-chiffre\">0,7 – 1 g/L</span></td><td><span class=\"kw-chiffre\">≥ 1 g/L</span></td></tr>\n          <tr><td><strong>Très élevé</strong></td><td><span class=\"kw-chiffre\">&lt; 0,55 g/L</span></td><td><span class=\"kw-chiffre\">0,55 – 0,7 g/L</span></td><td><span class=\"kw-chiffre\">≥ 0,7 g/L</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévention secondaire</span></strong></td><td><span class=\"kw-chiffre\">&lt; 0,55 g/L</span></td><td>—</td><td><span class=\"kw-chiffre\">≥ 0,55 g/L</span></td></tr>\n        </tbody>\n      </table>\n      <p>Chaque abaissement de <span class=\"kw-chiffre\">0,40 g/L</span> du <span class=\"kw-bio\">LDL-c</span> réduit d'environ <span class=\"kw-chiffre\">20 %</span> les événements cardiovasculaires.</p>\n      <div class=\"callout callout-info\">\n        <strong>Équations de référence — <span class=\"kw-def\">SCORE2</span> et <span class=\"kw-def\">SCORE2-OP</span> (ESC 2021).</strong> Basées sur le <span class=\"kw-bio\">cholestérol non-HDL</span>, le <span class=\"kw-etio\">tabagisme</span>, la <span class=\"kw-bio\">PAS</span>, l'âge et le sexe. Elles estiment le risque à <span class=\"kw-chiffre\">10 ans</span> d'événement cardiovasculaire (mortel ou non). Champ d'application : <strong><span class=\"kw-def\">SCORE2</span></strong> chez les sujets de <span class=\"kw-chiffre\">≥ 40 et &lt; 70 ans</span> ; <strong><span class=\"kw-def\">SCORE2-OP</span></strong> (older people) chez les sujets <span class=\"kw-chiffre\">≥ 70 ans</span>. <span class=\"kw-ci\">Non applicables</span> en cas de <span class=\"kw-etio\">diabète</span>, d'<span class=\"kw-etio\">insuffisance rénale chronique</span>, d'<span class=\"kw-etio\">hypercholestérolémie familiale</span> ou de <span class=\"kw-etio\">pathologie athéromateuse avérée</span> (patients d'emblée classés en risque élevé ou très élevé).\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Cas du sujet âgé.</strong> Le traitement hypolipémiant n'est pas recommandé en <span class=\"kw-def\">prévention primaire</span> après <span class=\"kw-chiffre\">80 ans</span> ; en <span class=\"kw-def\">prévention secondaire</span>, il reste indiqué sauf <span class=\"kw-alerte\">fragilité majeure</span> ou espérance de vie limitée.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 221 — <span class=\"kw-etio\">Athérome</span></em></p>","frequence":1},{"id":"223-2","rang":"A","rubrique":"Définition","titre":"Connaître les trois grands types de dyslipidémies","contenu":"<p>On distingue <strong>trois grands phénotypes</strong> de <span class=\"kw-etio\">dyslipidémie</span>, définis par l'anomalie lipidique dominante :</p>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Anomalie lipidique</th><th>Fredrickson</th><th>Aspect du sérum</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Hypercholestérolémie pure</span></strong></td><td>↑ <span class=\"kw-bio\">LDL-cholestérol</span> isolé</td><td><span class=\"kw-def\">IIa</span></td><td>Clair, limpide</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hypertriglycéridémie pure</span></strong></td><td>↑ <span class=\"kw-bio\">triglycérides</span> isolés</td><td><span class=\"kw-def\">I</span> · <span class=\"kw-def\">IV</span> · <span class=\"kw-def\">V</span></td><td>Opalescent à lactescent</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hyperlipidémie mixte</span></strong></td><td>↑ <span class=\"kw-bio\">LDL</span> + <span class=\"kw-bio\">triglycérides</span></td><td><span class=\"kw-def\">IIb</span> · <span class=\"kw-def\">III</span></td><td>Trouble</td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong>profil lipidique</strong> oriente le type : <span class=\"kw-etio\">hypercholestérolémie</span> prédominante si le rapport <span class=\"kw-bio\">CT / TG</span> <span class=\"kw-chiffre\">&gt; 2,5</span> ; <span class=\"kw-etio\">hypertriglycéridémie</span> prédominante si le rapport <span class=\"kw-bio\">TG / CT</span> <span class=\"kw-chiffre\">&gt; 2,5</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Un même <span class=\"kw-def\">génotype</span> peut donner plusieurs phénotypes lipidiques selon le contexte environnemental. Le phénotype est une <em>photographie instantanée</em> — il ne préjuge pas du mécanisme physiopathologique sous-jacent.\n      </div>","frequence":1},{"id":"223-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les relations entre dyslipidémies et athérosclérose","contenu":"<p>Trois anomalies lipidiques sont <span class=\"kw-etio\">athérogènes</span> et associées à une surmorbi-<span class=\"kw-def\">mortalité</span> cardiovasculaire :</p>\n      <ul>\n        <li>↑ du <span class=\"kw-bio\">LDL-cholestérol</span> — « mauvais <span class=\"kw-bio\">cholestérol</span> », <strong><span class=\"kw-def\">facteur de risque</span> le plus puissant</strong> ;</li>\n        <li>↑ des <span class=\"kw-bio\">triglycérides</span> — <span class=\"kw-def\">facteur de risque</span> moins puissant, rarement isolé ;</li>\n        <li>↓ du <span class=\"kw-bio\">HDL-cholestérol</span> — « bon <span class=\"kw-bio\">cholestérol</span> » protecteur ; seuils à risque : <span class=\"kw-chiffre\">&lt; 0,4 g/L</span> chez l'homme, <span class=\"kw-chiffre\">&lt; 0,5 g/L</span> chez la femme.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> Le <span class=\"kw-bio\">HDL-c</span> est un <em>marqueur</em> de risque utile en prédiction, mais <strong>il n'est pas une cible thérapeutique</strong>.\n      </div>\n      <p>L'atteinte topographique principale est la <span class=\"kw-clinique\">maladie coronaire</span> (risque relatif <span class=\"kw-chiffre\">×3</span> corrélé à l'élévation du <span class=\"kw-bio\">LDL</span>-c).</p>\n      <p>Étapes de l'<span class=\"kw-def\">athérogenèse</span> :</p>\n      <ol>\n        <li>Dépôt des <span class=\"kw-bio\">LDL</span> dans la paroi artérielle ;</li>\n        <li><span class=\"kw-def\">Oxydation</span> des <span class=\"kw-bio\">LDL</span> (favorisée par un temps de séjour allongé et l'inflammation locale) ;</li>\n        <li>Recrutement de <span class=\"kw-def\">macrophages</span> internalisant les <span class=\"kw-bio\">LDL</span> oxydées via les récepteurs scavengers ;</li>\n        <li>Transformation des macrophages en <strong><span class=\"kw-def\">cellules spumeuses</span></strong> ;</li>\n        <li>Constitution d'un <span class=\"kw-def\">centre lipidique nécrotique</span> recouvert d'une <span class=\"kw-def\">chape fibreuse</span>.</li>\n      </ol>\n      <p>Les <strong><span class=\"kw-def\">cellules spumeuses</span></strong> sont le marqueur histologique de la <span class=\"kw-clinique\">plaque</span> d'<span class=\"kw-etio\">athérome</span> ; les stries lipidiques sont retrouvées dès le jeune âge.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span class=\"kw-etio\">Athérome</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":1},{"id":"223-4","rang":"A","rubrique":"Dépistage","titre":"Savoir quand dépister une dyslipidémie ?","contenu":"<p>Le <span class=\"kw-bio\">bilan lipidique</span> de <span class=\"kw-def\">dépistage</span> est indiqué dans les situations suivantes :</p>\n      <ul>\n        <li>présence de <span class=\"kw-etio\">facteurs de risque cardiovasculaire</span> (estimation du RCV absolu) ;</li>\n        <li><span class=\"kw-etio\">enquête familiale</span> devant une <span class=\"kw-etio\">dyslipidémie</span> chez un apparenté ;</li>\n        <li>pathologie associée ou prescription pouvant induire une <span class=\"kw-etio\">dyslipidémie secondaire</span> ;</li>\n        <li>contrôle systématique lié à l'<span class=\"kw-etio\">âge</span> : vers <span class=\"kw-chiffre\">50 ans</span> chez l'homme, <span class=\"kw-chiffre\">60 ans</span> chez la femme.</li>\n      </ul>\n      <p>Si le bilan est <span class=\"kw-bio\">normal</span>, en l'absence d'événement cardiovasculaire, de prise de poids ou de nouveau <span class=\"kw-def\">facteur de risque</span> : il n'est pas justifié de le répéter avant <span class=\"kw-chiffre\">5 ans</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Quand suspecter une <span class=\"kw-etio\">dyslipidémie</span> primitive ?</strong>\n        <ul>\n          <li><span class=\"kw-etio\">hypercholestérolémie familiale</span> chez un parent ;</li>\n          <li><span class=\"kw-bio\">LDL-c</span> <span class=\"kw-chiffre\">≥ 1,9 g/L</span> chez l'adulte, ou <span class=\"kw-chiffre\">≥ 1,6 g/L</span> chez l'enfant ;</li>\n          <li><span class=\"kw-alerte\">maladie cardiovasculaire athéromateuse précoce</span> (personnelle ou familiale) ;</li>\n          <li><span class=\"kw-clinique\">xanthomes tendineux</span> ou <span class=\"kw-clinique\">arc cornéen</span> avant <span class=\"kw-chiffre\">45 ans</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire</em></p>","frequence":2},{"id":"223-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic positif et la classification des dyslipidémies","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> repose sur l'<strong><span class=\"kw-bio\">Exploration d'une Anomalie Lipidique (EAL)</span></strong>, réalisée après <span class=\"kw-chiffre\">12 h de jeûne</span>.</p>\n      <p>Dosages directs : <span class=\"kw-bio\">cholestérol total (CT)</span>, <span class=\"kw-bio\">triglycérides (TG)</span>, <span class=\"kw-bio\">HDL-cholestérol</span>. Le <span class=\"kw-bio\">LDL-c</span> est ensuite <strong>calculé</strong> par la <span class=\"kw-def\">formule de Friedewald</span> :</p>\n      <ul>\n        <li>en g/L : <span class=\"kw-chiffre\">LDL-c = CT − HDL − TG/5</span> ;</li>\n        <li>en mmol/L : <span class=\"kw-chiffre\">LDL-c = CT − HDL − TG/2,2</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Piège classique.</strong> Si <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 3,4 g/L</span> (<span class=\"kw-chiffre\">3,9 mmol/L</span>), la formule de Friedewald devient <span class=\"kw-alerte\">invalide</span> → <strong>dosage direct</strong> du <span class=\"kw-bio\">LDL</span>-c obligatoire.\n      </div>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur normale</th><th>Seuil pathologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">LDL-c</span></td><td><span class=\"kw-chiffre\">&lt; 1,6 g/L</span></td><td><span class=\"kw-etio\">Hypercholestérolémie</span> si <span class=\"kw-chiffre\">&gt; 1,6 g/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Triglycérides</span></td><td><span class=\"kw-chiffre\">&lt; 1,5 g/L</span></td><td><span class=\"kw-etio\">Hypertriglycéridémie</span> si <span class=\"kw-chiffre\">&gt; 1,5 g/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">HDL-c</span></td><td><span class=\"kw-chiffre\">&gt; 0,4 g/L</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Aspect du sérum et test de crémage</strong> (sérum laissé<span class=\"kw-chiffre\"> 12 h</span> à<span class=\"kw-chiffre\"> 4 °C</span>) :</p>\n      <ul>\n        <li>sérum <span class=\"kw-bio\">clair</span> → <span class=\"kw-etio\">hypercholestérolémie</span> ;</li>\n        <li>surnageant <span class=\"kw-bio\">crémeux</span> + sous-nageant clair → anomalie des <span class=\"kw-def\">chylomicrons</span> ;</li>\n        <li>surnageant <span class=\"kw-bio\">crémeux</span> + sous-nageant trouble → chylomicrons + <span class=\"kw-def\">VLDL</span> ;</li>\n        <li>sous-nageant <span class=\"kw-bio\">trouble</span> sans surnageant → anomalie des <span class=\"kw-def\">VLDL</span>.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/223/aspect-serum-fredrickson.png\"\n             alt=\"Quatre tubes de sérum illustrant les phénotypes plasmatiques : type IIa sérum clair, type I couche crémeuse de surface, type V anneau crémeux et sérum blanchâtre, type IIb/IV sérum trouble\"\n             loading=\"lazy\">\n        <figcaption>Aspect du sérum selon le phénotype lipidique. Sérum <strong>clair</strong> (type IIa) = <span class=\"kw-etio\">hypercholestérolémie</span> pure ; <strong>couche crémeuse</strong> de surface (type I) = chylomicrons ; <strong>anneau crémeux + sérum blanchâtre</strong> (type V) = chylomicrons + VLDL ; sérum <strong>trouble</strong> (type IIb/IV) = hyperlipidémie mixte. Source : fiche source EDN item 223.</figcaption>\n      </figure>\n      <p><strong><span class=\"kw-def\">Classification de Fredrickson</span></strong> — 5 types selon la lipoprotéine accumulée :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Lipoprotéine ↑</th><th>Sérum</th><th>Biologie</th><th>Manifestation / phénotype</th></tr></thead>\n        <tbody>\n          <tr><td><strong>I</strong></td><td><span class=\"kw-def\">Chylomicrons</span></td><td>Lactescent (couche crémeuse)</td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 10 g/L</span></td><td><span class=\"kw-alerte\">Pancréatite aiguë</span> ; hyperchylomicronémie primitive familiale</td></tr>\n          <tr><td><strong>IIa</strong></td><td><span class=\"kw-def\">LDL</span></td><td>Clair, limpide</td><td><span class=\"kw-bio\">LDL-c</span> <span class=\"kw-chiffre\">1,9 – 4 g/L</span> (hétérozygote)</td><td><span class=\"kw-etio\">Hypercholestérolémie</span> pure ; <span class=\"kw-clinique\">xanthomes tendineux</span> ; <span class=\"kw-etio\">athérosclérose</span></td></tr>\n          <tr><td><strong>IIb</strong></td><td><span class=\"kw-def\">LDL + VLDL</span></td><td>Opalescent</td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 1,5 g/L</span> + <span class=\"kw-bio\">LDL</span>-c élevé</td><td>Hyperlipidémie mixte ; <span class=\"kw-etio\">athérosclérose</span></td></tr>\n          <tr><td><strong>III</strong></td><td><span class=\"kw-def\">IDL</span></td><td>Opalescent</td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">≥ 1,5 g/L</span></td><td>Dysbêtalipoprotéinémie ; <span class=\"kw-clinique\">xanthomes des plis palmaires</span> (pathognomonique)</td></tr>\n          <tr><td><strong>IV</strong></td><td><span class=\"kw-def\">VLDL</span> isolée</td><td>Trouble</td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">≥ 1,5 g/L</span></td><td><span class=\"kw-etio\">Hypertriglycéridémie</span> ; risque de <span class=\"kw-alerte\">décompensation</span> en type V</td></tr>\n          <tr><td><strong>V</strong></td><td><span class=\"kw-def\">Chylomicrons + VLDL</span></td><td>Opalescent (anneau crémeux)</td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 10 g/L</span></td><td><span class=\"kw-alerte\">Pancréatite aiguë</span> ; hyperchylomicronémie primitive familiale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-alerte\">hypertriglycéridémie majeure</span> (<span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 10 g/L</span>) expose à la <span class=\"kw-alerte\">pancréatite aiguë</span> — risque majeur au-delà de <span class=\"kw-chiffre\">30 g/L</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 358 — <span class=\"kw-def\">Pancréatite aiguë</span></em></p>","frequence":8},{"id":"223-6","rang":"A","rubrique":"Contenu multimédia","titre":"Connaître les manifestations cliniques des dyslipidémies : xanthelasma","contenu":"<p>Les manifestations cliniques sont des <strong><span class=\"kw-clinique\">dépôts lipidiques extravasculaires</span></strong>. Banals isolément, ils prennent une <strong>valeur sémiologique</strong> lorsqu'ils surviennent <span class=\"kw-chiffre\">avant 60 ans</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Hypercholestérolémie</span></th><th><span class=\"kw-etio\">Hypertriglycéridémie</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Dépôts lipidiques :</strong> <span class=\"kw-clinique\">arc cornéen</span> (gérontoxon) ; <span class=\"kw-clinique\">xanthélasma</span> = dépôts jaune-orangé sur les paupières<br>\n              <strong>Xanthomes (plus rares) :</strong> <span class=\"kw-clinique\">xanthomes tendineux</span> des extenseurs des doigts et du tendon calcanéen ; <span class=\"kw-clinique\">xanthomes plans cutanés</span> et <span class=\"kw-clinique\">tubéreux</span> uniquement dans les formes <strong>homozygotes</strong><br>\n              <strong>Complications :</strong> athéromateuses, parfois révélatrices — <span class=\"kw-alerte\">IDM</span> ; <span class=\"kw-alerte\">AOMI</span> ; <span class=\"kw-alerte\">AVC</span>\n            </td>\n            <td>\n              <strong>Syndrome hyperchylomicronémique</strong> (exceptionnel) : <span class=\"kw-clinique\">hépato-splénomégalie stéatosique</span> ; <span class=\"kw-clinique\">douleurs abdominales</span><br>\n              <strong>Œil :</strong> <span class=\"kw-clinique\">lipémie rétinienne</span> (lactescence des vaisseaux rétiniens au <span class=\"kw-imagerie\">fond d'œil</span>)<br>\n              <strong>Peau :</strong> <span class=\"kw-clinique\">xanthomatose éruptive</span> — <span class=\"kw-clinique\">éruption</span> punctiforme blanc-jaunâtre, <strong>indolore</strong>, <strong>non prurigineuse</strong>, épargnant la face<br>\n              <strong>Complication :</strong> <span class=\"kw-alerte\">pancréatite aiguë</span> si <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 10 g/L</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-clinique\">xanthélasma</span> est évocateur mais <strong>non pathognomonique</strong>. Les <span class=\"kw-clinique\">xanthomes tendineux</span> sont en revanche <strong>pathognomoniques</strong> d'une <span class=\"kw-etio\">hypercholestérolémie</span> familiale, et la <span class=\"kw-clinique\">coloration orangée des plis palmaires</span> est pathognomonique de la dysbêtalipoprotéinémie (type III).</p>\n      <div class=\"callout callout-info\">\n        <strong>À compléter (image).</strong> Les photos cliniques attendues pour cet objectif « Contenu multimédia » (xanthélasma, arc cornéen, xanthomes tendineux, xanthomatose éruptive) proviennent du Collège et ne figurent pas dans les fiches sources. Kevin les déposera dans <code>assets/images/223/</code> lors d'un B-FIX ultérieur.\n      </div>\n      <!-- TODO Kevin : déposer les photos cliniques (xanthelasma, arc-cornéen, xanthomes tendineux, xanthomatose éruptive) dans assets/images/223/ -->","frequence":6},{"id":"223-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d’hyperlipidémies secondaires","contenu":"<p>Devant toute <span class=\"kw-etio\">dyslipidémie</span>, il faut systématiquement éliminer une <strong><span class=\"kw-etio\">cause secondaire</span></strong> avant de retenir une <span class=\"kw-etio\">dyslipidémie</span> primitive.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Hypercholestérolémie</span> secondaire</th><th>Hyperlipidémie mixte secondaire</th><th><span class=\"kw-etio\">Hypertriglycéridémie</span> secondaire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Causes communes :</strong> <span class=\"kw-etio\">grossesse</span> ; <span class=\"kw-etio\">syndrome néphrotique</span> ; <span class=\"kw-etio\">hypothyroïdie</span> ; <span class=\"kw-etio\">déficit en GH</span><br>\n              <strong>Iatrogènes :</strong> <span class=\"kw-ttt\">diurétiques thiazidiques</span> ; <span class=\"kw-ttt\">immunosuppresseurs</span> (<span class=\"kw-ttt\">ciclosporine</span>, sirolimus, évérolimus) ; <span class=\"kw-ttt\">bexarotène</span><br>\n              <strong>Spécifiques :</strong> <span class=\"kw-etio\">cholestase</span> ; <span class=\"kw-etio\">anorexie mentale</span>\n            </td>\n            <td>\n              <strong>Causes communes :</strong> <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-def\">syndrome néphrotique</span> ; <span class=\"kw-def\">hypothyroïdie</span> ; déficit en GH<br>\n              <strong>Iatrogènes :</strong> identiques à l'<span class=\"kw-etio\">hypercholestérolémie</span> secondaire<br>\n              <strong>Spécifiques :</strong> <span class=\"kw-etio\">insuffisance rénale chronique</span> ; <span class=\"kw-etio\">diabète mal équilibré</span> ; <span class=\"kw-etio\">hypercorticisme</span> ; <span class=\"kw-ttt\">antiprotéases</span> ; <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-ttt\">rétinoïdes</span>\n            </td>\n            <td>\n              <strong>Causes communes :</strong> <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-def\">syndrome néphrotique</span> ; <span class=\"kw-def\">hypothyroïdie</span> ; déficit en GH<br>\n              <strong>Métaboliques :</strong> <span class=\"kw-etio\">alcoolisme</span> ; <span class=\"kw-etio\">obésité</span> et <span class=\"kw-etio\">syndrome métabolique</span> ; <span class=\"kw-etio\">acromégalie</span> ; <span class=\"kw-etio\">VIH</span><br>\n              <strong>Iatrogènes :</strong> <span class=\"kw-ttt\">œstrogènes oraux</span> ; <span class=\"kw-ttt\">β-bloquants</span> ; <span class=\"kw-ttt\">interféron alpha</span> ; <span class=\"kw-ttt\">antirétroviraux</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Piège thérapeutique.</strong> Les hyperlipidémies secondaires régressent avec le <strong>traitement étiologique</strong> — <span class=\"kw-ci\">ne pas prescrire d'hypolipémiant</span> (inutile, voire dangereux : risque musculaire d'une <span class=\"kw-ttt\">statine</span> en cas d'<span class=\"kw-def\">hypothyroïdie</span> non corrigée).\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Exception.</strong> La <span class=\"kw-etio\">dyslipidémie</span> associée au <span class=\"kw-etio\">DT2</span> et au <span class=\"kw-etio\">syndrome métabolique</span> ne régresse <strong>pas</strong> avec la seule normalisation glycémique — elle est liée à l'<span class=\"kw-def\">insulinorésistance</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 247 — <span class=\"kw-def\">Diabète</span></em></p>","frequence":4},{"id":"223-8","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir quel bilan biologique prescrire à la recherche d’une dyslipidémie secondaire","contenu":"<p>Devant la découverte d'une <span class=\"kw-etio\">dyslipidémie</span>, un <strong>bilan <span class=\"kw-ttt\">biologique</span> minimal</strong> est prescrit à la recherche d'une cause secondaire :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Cause secondaire recherchée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Glycémie à jeun</span></td><td><span class=\"kw-etio\">Diabète</span></td></tr>\n          <tr><td><span class=\"kw-bio\">TSH</span></td><td><span class=\"kw-etio\">Hypothyroïdie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan hépatique</span></td><td><span class=\"kw-etio\">Cholestase</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Créatininémie</span></td><td><span class=\"kw-etio\">Insuffisance rénale chronique</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Protéinurie</span></td><td><span class=\"kw-etio\">Syndrome néphrotique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Si le <span class=\"kw-bio\">LDL-c</span> est <span class=\"kw-chiffre\">≥ 1,9 g/L</span>, il est recommandé de rechercher une <span class=\"kw-def\">hypercholestérolémie familiale hétérozygote</span> — le bilan ne se limite donc pas aux seules causes secondaires.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":1},{"id":"223-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des dyslipidémies (voir item 330)","contenu":"<p>Préalable : une <span class=\"kw-etio\">dyslipidémie secondaire</span> ou <span class=\"kw-etio\">iatrogène</span> se traite par sa <strong>cause</strong>, jamais par un hypolipémiant d'emblée.</p>\n      <p><strong><span class=\"kw-etio\">Hypercholestérolémie</span> isolée</strong> — stratégie d'escalade :</p>\n      <ul>\n        <li>1ʳᵉ intention : <span class=\"kw-ttt\">statine</span>, débutée à faible posologie puis augmentée selon efficacité et tolérance ;</li>\n        <li>objectif non atteint : ↑ dose ou <span class=\"kw-ttt\">statine</span> plus puissante, puis <span class=\"kw-ttt\">ézétimibe</span>, puis <span class=\"kw-ttt\">colestyramine</span> ;</li>\n        <li><span class=\"kw-ci\">intolérance</span> aux <span class=\"kw-ttt\">statines</span> : <span class=\"kw-ttt\">ézétimibe</span> voire <span class=\"kw-ttt\">colestyramine</span> ;</li>\n        <li><span class=\"kw-ttt\">anti-PCSK9</span> (alirocumab, évolocumab) : hypercholestérolémies familiales sévères, sur avis spécialisé.</li>\n      </ul>\n      <p><strong><span class=\"kw-etio\">Hypertriglycéridémie</span> isolée :</strong> <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">1,5 – 5 g/L</span> → diététique seule ; <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 5 g/L</span> → diététique puis <span class=\"kw-ttt\">fibrate</span> (objectif <span class=\"kw-chiffre\">&lt; 5 g/L</span> pour prévenir la pancréatite), puis <span class=\"kw-ttt\">acides gras oméga-3</span> en association.</p>\n      <p><strong>Hyperlipidémie mixte :</strong> objectif <span class=\"kw-bio\">LDL-c</span> prioritaire (si TG &lt;<span class=\"kw-chiffre\"> 5 g/L</span>) → diététique + <span class=\"kw-ttt\">statine</span> ± <span class=\"kw-ttt\">ézétimibe</span> ; <span class=\"kw-ttt\">fénofibrate</span> ajouté si haut risque <span class=\"kw-bio\">CV</span> + TG <span class=\"kw-chiffre\">≥ 2 g/L</span> + <span class=\"kw-bio\">HDL</span> bas.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme</th><th>Effet lipidique</th><th>Effets indésirables clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Statine</span></strong></td><td>Inhibe l'HMG-CoA-réductase</td><td>↓ <span class=\"kw-bio\">LDL</span>-c <span class=\"kw-chiffre\">25–45 %</span></td><td><span class=\"kw-alerte\">Myalgies</span> ; ↑ <span class=\"kw-bio\">CPK</span> ; ↑ transaminases ; surrisque <span class=\"kw-def\">DT2</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Ézétimibe</span></strong></td><td>↓ absorption intestinale du <span class=\"kw-bio\">cholestérol</span></td><td>↓ <span class=\"kw-bio\">LDL</span>-c <span class=\"kw-chiffre\">20 %</span></td><td><span class=\"kw-clinique\">Myalgies</span> ; troubles digestifs</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Colestyramine</span></strong> (résine)</td><td>↓ réabsorption des sels biliaires</td><td>↓ <span class=\"kw-bio\">LDL</span>-c <span class=\"kw-chiffre\">20 %</span> ; <span class=\"kw-alerte\">↑ TG</span></td><td>Troubles digestifs ; ↓ absorption des vitamines liposolubles</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Fibrate</span></strong></td><td>Activateur des PPARα</td><td>↓ TG <span class=\"kw-chiffre\">20–40 %</span></td><td><span class=\"kw-clinique\">Myalgies</span> ; lithiase biliaire ; ↑ <span class=\"kw-bio\">CPK</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Oméga-3</span></strong> (EPA, DHA)</td><td>↓ production des VLDL</td><td>↓ TG <span class=\"kw-chiffre\">10–30 %</span></td><td>Troubles digestifs</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indication</span>.</strong> L'association <span class=\"kw-ci\">statine + gemfibrozil</span> est <span class=\"kw-ci\">contre-indiquée</span> (risque de <span class=\"kw-alerte\">rhabdomyolyse</span>). La <span class=\"kw-def\">surveillance</span> musculaire est avant tout <strong>clinique</strong> — dosage des <span class=\"kw-bio\">CPK</span> uniquement en cas de symptômes ou de <span class=\"kw-def\">terrain</span> à risque.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":3},{"id":"223-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles hygiéno-diététiques","contenu":"<p>Les <strong><span class=\"kw-ttt\">règles hygiéno-diététiques</span> (RHD)</strong> sont la première étape du traitement : elles précèdent — voire remplacent — le traitement <span class=\"kw-etio\">médicamenteux</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Dyslipidémie</span></th><th>À favoriser</th><th>À limiter / éviter</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hypercholestérolémie</span></strong></td>\n            <td><span class=\"kw-clinique\">fibres solubles</span> (céréales complètes, légumineuses, fruits, légumes) ; <span class=\"kw-clinique\">phytostérols</span> ; <span class=\"kw-clinique\">acides gras insaturés</span> (~<span class=\"kw-chiffre\">15 %</span>)</td>\n            <td>graisses totales <span class=\"kw-chiffre\">&lt; 35 %</span> de l'apport calorique ; <span class=\"kw-clinique\">acides gras saturés</span> <span class=\"kw-chiffre\">&lt; 10 %</span> ; <span class=\"kw-clinique\">acides gras trans</span> ; <span class=\"kw-ci\">levure rouge de riz</span> (mêmes effets indésirables que les <span class=\"kw-ttt\">statines</span>, <span class=\"kw-ci\">à proscrire</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hypertriglycéridémie</span></strong></td>\n            <td><span class=\"kw-ttt\">réduction</span> du <span class=\"kw-clinique\">surpoids</span> (apports hypocaloriques <span class=\"kw-chiffre\">−20 %</span>) ; activité physique</td>\n            <td><span class=\"kw-ci\">alcool</span> (test d'éviction <span class=\"kw-chiffre\">1 semaine</span>) ; <span class=\"kw-clinique\">sucres simples</span> et boissons sucrées</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-alerte\">décompensation</span> avec <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">&gt; 30 g/L</span> est une <span class=\"kw-alerte\">urgence nutritionnelle</span> → <strong>diète hydrique transitoire</strong> jusqu'à normalisation des <span class=\"kw-bio\">triglycérides</span>.\n      </div>\n      <p><strong><span class=\"kw-ttt\">RHD</span> globales de prévention de l'<span class=\"kw-etio\">athérosclérose</span> :</strong> régime <span class=\"kw-def\">méditerranéen</span> (huile d'olive vierge, fruits à coque <span class=\"kw-chiffre\">30 g/j</span>, poisson gras <span class=\"kw-chiffre\">1×/sem</span>, <span class=\"kw-ttt\">réduction</span> de la viande rouge) ; <span class=\"kw-clinique\">activité physique</span> <span class=\"kw-chiffre\">≥ 30 min/j</span>, <span class=\"kw-chiffre\">5 j/sem</span> (soit <span class=\"kw-chiffre\">≥ 2 h 30/sem</span> d'intensité modérée).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 253 — <span class=\"kw-etio\">Obésité</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-etio\">dyslipidémie</span> habituellement chronique, sauf l'<span class=\"kw-alerte\">hypertriglycéridémie majeure</span> qui expose à la <span class=\"kw-etio\">pancréatite aiguë</span><br><strong>Seuil de risque :</strong> risque de <span class=\"kw-etio\">pancréatite</span> dès <span class=\"kw-chiffre\">TG > 10 g/L</span>, risque majeur si <span class=\"kw-chiffre\">> 30 g/L</span> (phénotype <span class=\"kw-etio\">hyperchylomicronémie</span>, types 1/5)<br><strong>1er geste :</strong> <span class=\"kw-chiffre\">TG > 30 g/L</span> = <span class=\"kw-alerte\">urgence nutritionnelle</span> → <span class=\"kw-ttt\">diète hydrique transitoire</span> jusqu'à normalisation ou stabilisation des TG</p>","hospit":"<p><strong>Ambulatoire :</strong> la majorité des dyslipidémies se gèrent en ville (<span class=\"kw-ttt\">RHD</span> ± <span class=\"kw-ttt\">statine</span>)<br><strong>Avis spécialisé :</strong> <span class=\"kw-etio\">hyperchylomicronémies</span> (équipe spécialisée), <span class=\"kw-etio\">hypercholestérolémies familiales sévères</span>, patient à <span class=\"kw-chiffre\">RCV élevé</span> intolérant aux <span class=\"kw-ttt\">statines</span>, prescription de <span class=\"kw-ttt\">fibrate</span> ou d'<span class=\"kw-ttt\">oméga 3</span><br><strong>Médicament d'exception :</strong> <span class=\"kw-ttt\">anti-PCSK9</span> (<span class=\"kw-ttt\">alirocumab</span>, <span class=\"kw-ttt\">évolocumab</span>) initié uniquement par un spécialiste (endocrinologue, médecine interne, cardiologue), accord préalable de l'assurance maladie<br><strong><span class=\"kw-def\">Dépistage</span> familial :</strong> devant une <span class=\"kw-etio\">hypercholestérolémie familiale</span>, dépistage en cascade des apparentés au <span class=\"kw-chiffre\">1er degré</span> ; <span class=\"kw-bio\">tests génétiques</span> en centre spécialisé</p>","redflags":"<ul><li><span class=\"kw-bio\">LDL-C ≥ 1,9 g/L</span> chez l'adulte (ou <span class=\"kw-chiffre\">≥ 1,6 g/L</span> chez l'enfant) → rechercher une <span class=\"kw-etio\">hypercholestérolémie familiale</span> hétérozygote</li><li><span class=\"kw-clinique\">Xanthomes tendineux</span> ou <span class=\"kw-clinique\">arc cornéen avant 45 ans</span> → évocateurs d'une <span class=\"kw-etio\">dyslipidémie primitive</span></li><li><span class=\"kw-etio\">Maladie cardiovasculaire athéromateuse précoce</span>, personnelle ou familiale</li><li>Complications athéromateuses parfois révélatrices : <span class=\"kw-alerte\">IDM</span>, <span class=\"kw-alerte\">AVC</span>, <span class=\"kw-etio\">AOMI</span></li><li><span class=\"kw-chiffre\">TG > 10 g/L</span> → risque de <span class=\"kw-alerte\">pancréatite aiguë</span> (majeur si <span class=\"kw-chiffre\">> 30 g/L</span>)</li><li><span class=\"kw-etio\">Hypercholestérolémie familiale homozygote</span> : complications CV dès la <span class=\"kw-chiffre\">1re décennie</span>, décès vers <span class=\"kw-chiffre\">20 ans</span> en l'absence de traitement</li></ul>","principes":"<p>Traiter d'abord la cause si <span class=\"kw-etio\">dyslipidémie secondaire</span> ; sinon stratégie selon le type de <span class=\"kw-etio\">dyslipidémie</span> et l'objectif de <span class=\"kw-bio\">LDL-C</span> fixé par le <span class=\"kw-def\">risque cardiovasculaire global</span>.</p><p><strong><span class=\"kw-etio\">Dyslipidémie</span> secondaire / <span class=\"kw-etio\">iatrogène</span></strong></p><ul><li>Ne pas prescrire d'<span class=\"kw-ttt\">hypolipémiant</span> sans traiter la maladie causale (inutile voire dangereux)</li><li>Causes : <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">syndrome néphrotique</span>, <span class=\"kw-etio\">cholestase</span>, <span class=\"kw-etio\">alcoolisme</span>, <span class=\"kw-ttt\">œstrogènes oraux</span>, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">diurétiques thiazidiques</span></li><li>L'hyperlipidémie du <span class=\"kw-etio\">DT2</span> / <span class=\"kw-etio\">syndrome métabolique</span> ne régresse pas avec la normalisation glycémique</li></ul><p><strong>Hypercholestérolémie isolée</strong></p><p>Objectif <span class=\"kw-bio\">LDL-C</span> selon le RCV : <span class=\"kw-chiffre\">< 1,16 g/L</span> (faible), <span class=\"kw-chiffre\">< 1 g/L</span> (modéré), <span class=\"kw-chiffre\">< 0,7 g/L</span> (élevé), <span class=\"kw-chiffre\">< 0,55 g/L</span> (très élevé / prévention secondaire)</p><ul><li>1re intention : <span class=\"kw-ttt\">statine</span> à faible posologie puis augmentation progressive</li><li>Escalade : augmenter la dose ou <span class=\"kw-ttt\">statine plus puissante</span> > <span class=\"kw-ttt\">ézétimibe</span> > <span class=\"kw-ttt\">colestyramine</span></li><li>Intolérance aux <span class=\"kw-ttt\">statines</span> : <span class=\"kw-ttt\">ézétimibe</span> voire <span class=\"kw-ttt\">colestyramine</span></li><li><span class=\"kw-ttt\">Anti-PCSK9</span> réservé aux <span class=\"kw-etio\">hypercholestérolémies familiales sévères</span> (avis spécialisé)</li></ul><p><strong>Hypertriglycéridémie isolée</strong></p><ul><li><span class=\"kw-chiffre\">TG 1,5 – 5 g/L</span> : <span class=\"kw-ttt\">traitement diététique</span> seul</li><li><span class=\"kw-chiffre\">TG > 5 g/L</span> : RHD spécifiques puis <span class=\"kw-ttt\">fibrate</span> si TG restent élevés (objectif <span class=\"kw-chiffre\">TG < 5 g/L</span> pour prévenir la pancréatite)</li><li>Si TG persistants sous fibrate : ajouter des <span class=\"kw-ttt\">acides gras oméga 3</span> (EPA-DHA)</li></ul><p><strong>Hyperlipidémie mixte</strong></p><p><span class=\"kw-ci\">Gemfibrozil contre-indiqué</span> avec les <span class=\"kw-ttt\">statines</span></p><ul><li>Objectif <span class=\"kw-bio\">LDL-C</span> prioritaire (tant que <span class=\"kw-chiffre\">TG < 5 g/L</span>)</li><li><span class=\"kw-ttt\">RHD</span> + activité physique, puis <span class=\"kw-ttt\">statine</span> ± <span class=\"kw-ttt\">ézétimibe</span></li><li>Si objectif LDL-C atteint + <span class=\"kw-chiffre\">TG ≥ 2 g/L</span> + <span class=\"kw-bio\">HDL-C bas</span> + haut RCV : ajouter du <span class=\"kw-ttt\">fénofibrate</span></li></ul>","suivi":"<p><strong>Efficacité :</strong> <span class=\"kw-bio\">bilan lipidique</span> toutes les <span class=\"kw-chiffre\">4–6 semaines</span> en <span class=\"kw-def\">prévention secondaire</span> / très haut RCV, tous les <span class=\"kw-chiffre\">2–3 mois</span> après instauration sur RCV faible-modéré ou après adaptation, puis <span class=\"kw-chiffre\">1 à 2x/an</span> une fois l'objectif atteint<br><strong>Tolérance musculaire :</strong> <span class=\"kw-def\">surveillance</span> clinique des <span class=\"kw-clinique\">myalgies</span> ; doser les <span class=\"kw-bio\">CPK</span> si symptômes, arrêt du traitement si <span class=\"kw-chiffre\">CPK > 5N</span> + contrôle toutes les <span class=\"kw-chiffre\">2 semaines</span><br><strong>Tolérance hépatique :</strong> <span class=\"kw-bio\">ALAT</span> avant traitement, à <span class=\"kw-chiffre\">8 semaines</span> puis <span class=\"kw-chiffre\">1x/an</span> ; arrêt ou <span class=\"kw-ttt\">réduction</span> si <span class=\"kw-chiffre\">ALAT ≥ 3N</span><br><strong>Autres :</strong> dépister un <span class=\"kw-etio\">diabète de novo</span> sous <span class=\"kw-ttt\">statine</span> ; bilan normal sans FR ni événement → ne pas répéter avant <span class=\"kw-chiffre\">5 ans</span></p>"},"liensGlobaux":[{"href":"https://www.sfendocrino.org/items-222-223-facteurs-de-risque-cardiovasculaire-prevention-dyslipidemies/","label":"SFE — Items 222 223 facteurs de risque cardiovasculaire prevention dyslipidemies"},{"href":"https://www.sfcardio.fr/page/chapitre-3-item-223-dyslipidemies","label":"SFC — Chapitre 3 item 223 dyslipidemies"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-etio\">Dyslipidémie</span> confirmée sur EAL à jeun — rechercher une cause secondaire — Bilan minimal : <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">protéinurie</span>","detail":"<h4>CAT — <span class=\"kw-etio\">Dyslipidémie</span> de l'adulte — Du <span class=\"kw-bio\">bilan lipidique</span> à jeun (<span class=\"kw-chiffre\">12 h</span>) au choix thérapeutique selon le type de dyslipidémie et le risque CV</h4>","branches":[{"to":"t-secondaire","label":"Cause secondaire / iatrogène présente","color":"blue"},{"to":"q-type","label":"Dyslipidémie primitive (bilan de cause négatif)","color":"green"}]},{"id":"t-secondaire","kind":"terminal","label":"Traiter d'abord la maladie causale","color":"blue","detail":"<h4>Conduite</h4><ul><li>Ne pas prescrire d'<span class=\"kw-ttt\">hypolipémiant</span> sans traiter la cause (inutile voire dangereux)</li><li>Causes : <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">syndrome néphrotique</span>, <span class=\"kw-etio\">cholestase</span>, <span class=\"kw-etio\">alcoolisme</span>, <span class=\"kw-ttt\">œstrogènes oraux</span>, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">diurétiques thiazidiques</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>L'hyperlipidémie du <span class=\"kw-etio\">DT2</span> / <span class=\"kw-etio\">syndrome métabolique</span> ne régresse pas avec la normalisation glycémique</li></ul>"},{"id":"q-type","kind":"decision","label":"Profil lipidique dominant (rapport CT/TG, aspect du sérum) ?","branches":[{"to":"q-chol","label":"Hypercholestérolémie isolée (CT/TG > 2,5, sérum clair)","color":"green"},{"to":"q-tg","label":"Hypertriglycéridémie isolée (TG/CT > 2,5, sérum opalescent)","color":"amber"},{"to":"t-mixte","label":"Hyperlipidémie mixte (sérum trouble)","color":"amber"}]},{"id":"q-chol","kind":"decision","label":"Objectif de <span class=\"kw-bio\">LDL</span>-C (selon le RCV) atteint sous <span class=\"kw-ttt\">RHD</span> à<span class=\"kw-chiffre\"> 3 mois</span> ? — Cibles : <span class=\"kw-chiffre\">< 1,16 g/L</span> (faible) à <span class=\"kw-chiffre\">< 0,55 g/L</span> (très élevé / prévention secondaire)","branches":[{"to":"t-chol-rhd","label":"Oui","color":"green"},{"to":"t-chol-statine","label":"Non (ou LDL-C élevé d'emblée)","color":"amber"}]},{"id":"t-chol-rhd","kind":"terminal","label":"Poursuite des RHD + surveillance","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> : acides gras insaturés, fibres, limiter les graisses <span class=\"kw-chiffre\">< 35%</span> et les AG saturés <span class=\"kw-chiffre\">< 10%</span></li></ul><h4>Surveillance</h4><ul><li>Bilan lipidique <span class=\"kw-chiffre\">1 à 2x/an</span></li><li>Si bilan normal sans FR ni événement CV : ne pas répéter avant <span class=\"kw-chiffre\">5 ans</span></li></ul>"},{"id":"t-chol-statine","kind":"terminal","label":"Statine en 1re intention","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Statine</span> à faible dose puis augmentation progressive (choix selon <span class=\"kw-bio\">LDL</span>-C initial et objectif)</li><li>Escalade : augmenter la dose / <span class=\"kw-ttt\">statine plus puissante</span> > <span class=\"kw-ttt\">ézétimibe</span> > <span class=\"kw-ttt\">colestyramine</span></li><li><span class=\"kw-ci\">Intolérance</span> : <span class=\"kw-ttt\">ézétimibe</span> voire <span class=\"kw-ttt\">colestyramine</span> ; <span class=\"kw-ttt\">anti-PCSK9</span> si <span class=\"kw-etio\">HF sévère</span> (avis spécialisé)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">ALAT</span> avant / à <span class=\"kw-chiffre\">8 sem</span> / <span class=\"kw-chiffre\">1x/an</span> — arrêt si <span class=\"kw-chiffre\">ALAT ≥ 3N</span></li><li><span class=\"kw-bio\">CPK</span> si <span class=\"kw-clinique\">myalgies</span> — arrêt si <span class=\"kw-chiffre\">CPK > 5N</span></li></ul>"},{"id":"q-tg","kind":"decision","label":"Niveau de triglycérides ?","branches":[{"to":"t-tg-diet","label":"TG 1,5 – 5 g/L","color":"green"},{"to":"t-tg-fibrate","label":"TG 5 – 30 g/L","color":"amber"},{"to":"t-urgence","label":"TG > 30 g/L","color":"red"}]},{"id":"t-tg-diet","kind":"terminal","label":"Traitement diététique seul","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Mesures diététiques</span> propres aux hyperTG, sans hypolipémiant</li><li><span class=\"kw-ttt\">Réduction</span> du surpoids (<span class=\"kw-chiffre\">-20%</span>), diminution / arrêt de l'<span class=\"kw-ttt\">alcool</span>, réduction des sucres simples (<span class=\"kw-chiffre\">< 45%</span> des glucides)</li></ul>"},{"id":"t-tg-fibrate","kind":"terminal","label":"RHD spécifiques ± fibrate","color":"amber","detail":"<h4>Traitement</h4><ul><li>Objectif : réduire les <span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">< 5 g/L</span> pour prévenir la <span class=\"kw-etio\">pancréatite</span></li><li>RHD spécifiques ; si TG restent <span class=\"kw-chiffre\">> 5 g/L</span> → <span class=\"kw-ttt\">fibrate</span> ; si toujours élevés → ajout d'<span class=\"kw-ttt\">acides gras oméga 3</span> (EPA-DHA)</li></ul><h4>Conduite</h4><ul><li>Risque de <span class=\"kw-alerte\">pancréatite aiguë</span> dès <span class=\"kw-chiffre\">TG > 10 g/L</span></li></ul>"},{"id":"t-urgence","kind":"terminal","label":"Urgence nutritionnelle","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-alerte\">Décompensation</span> à <span class=\"kw-chiffre\">TG > 30 g/L</span> = <span class=\"kw-alerte\">urgence nutritionnelle</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Diète hydrique transitoire</span> jusqu'à normalisation / stabilisation des TG</li><li>Prise en charge par une équipe spécialisée</li><li>Phénotype : <span class=\"kw-etio\">hyperchylomicronémies primitives familiales</span> (types 1/5), risque de <span class=\"kw-alerte\">pancréatite récidivante</span></li></ul>"},{"id":"t-mixte","kind":"terminal","label":"Priorité au LDL-C puis fibrate conditionnel","color":"amber","detail":"<h4>Traitement</h4><ul><li>Objectif <span class=\"kw-bio\">LDL-C</span> prioritaire (si <span class=\"kw-chiffre\">TG < 5 g/L</span>)</li><li><span class=\"kw-ttt\">RHD</span> + activité physique, puis <span class=\"kw-ttt\">statine</span> ± <span class=\"kw-ttt\">ézétimibe</span></li><li>Si objectif LDL-C atteint + <span class=\"kw-chiffre\">TG ≥ 2 g/L</span> + <span class=\"kw-bio\">HDL-C bas</span> + haut RCV → <span class=\"kw-ttt\">fénofibrate</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">Gemfibrozil contre-indiqué</span> avec les <span class=\"kw-ttt\">statines</span></li></ul>"}]},"cards":[{"i":"17b6a04ef245","n":223,"o":"223-1","u":"Définition","t":"Connaître l’évaluation du risque cardiovasculaire global","q":"Quelles sont les différentes catégories de risque cardiovasculaire utilisées pour l'évaluation globale ?","a":"<p>On distingue <strong>cinq catégories</strong> de risque cardiovasculaire :</p><ul><li><strong>Faible</strong></li><li><strong>Modéré</strong></li><li><strong>Élevé</strong></li><li><strong>Très élevé</strong></li><li><strong>Prévention secondaire</strong> (patient ayant déjà fait un événement athéromateux)</li></ul>"},{"i":"1d0435691b8a","n":223,"o":"223-1","u":"Définition","t":"Connaître l’évaluation du risque cardiovasculaire global","q":"Comment l'évaluation du risque cardiovasculaire et la prise en charge des dyslipidémies sont-elles adaptées chez le sujet âgé ?","a":"<p>Chez le sujet âgé :</p><ul><li>Le score de risque (<strong>SCORE</strong>) ne peut pas être calculé <strong>après 65 ans</strong>.</li><li>Le traitement hypolipémiant n'est pas recommandé en <strong>prévention primaire après 80 ans</strong>.</li><li>En <strong>prévention secondaire</strong>, le traitement reste indiqué sauf en cas de <strong>fragilité majeure</strong> ou d'<strong>espérance de vie limitée</strong>.</li></ul>"},{"i":"c7284aacf228","n":223,"o":"223-1","u":"Définition","t":"Connaître l’évaluation du risque cardiovasculaire global","q":"Quel est l'impact de l'abaissement du LDL-cholestérol sur les événements cardiovasculaires ?","a":"<p>Chaque abaissement de <strong>0,40 g/L</strong> du LDL-cholestérol réduit d'environ <strong>20 %</strong> les événements cardiovasculaires.</p>"},{"i":"cf9ebf237c14","n":223,"o":"223-1","u":"Définition","t":"Connaître l’évaluation du risque cardiovasculaire global","q":"Quels sont les objectifs de LDL-cholestérol en prévention secondaire et pour un risque très élevé ?","a":"<p>Pour la catégorie de risque <strong>très élevé</strong>, l'objectif de LDL-cholestérol est <strong>&lt; 0,55 g/L</strong>.</p><p>Pour la <strong>prévention secondaire</strong>, l'objectif de LDL-cholestérol est également <strong>&lt; 0,55 g/L</strong>.</p>"},{"i":"df3df0769242","n":223,"o":"223-1","u":"Définition","t":"Connaître l’évaluation du risque cardiovasculaire global","q":"Quel est le rôle de l'évaluation du risque cardiovasculaire global dans la prise en charge des dyslipidémies ?","a":"<p>L'évaluation du risque cardiovasculaire (RCV) global est le <strong>préalable obligatoire</strong> à toute décision thérapeutique concernant les lipides. Elle permet de fixer l'<strong>objectif de LDL-cholestérol</strong> à atteindre et le <strong>seuil de mise sous traitement médicamenteux</strong>.</p>"},{"i":"1dc3b5d2e617","n":223,"o":"223-10","u":"Prise en charge","t":"Connaître les règles hygiéno-diététiques","q":"Quelles sont les règles hygiéno-diététiques globales recommandées pour la prévention de l'athérosclérose ?","a":"<ul><li>Adopter un <strong>régime méditerranéen</strong> (privilégier l'huile d'olive vierge, consommer 30 g/jour de fruits à coque, du poisson gras 1 fois/semaine et réduire la consommation de viande rouge).</li><li>Pratiquer une <strong>activité physique</strong> d'au moins 30 minutes par jour, 5 jours par semaine (soit un minimum de 2h30 par semaine d'intensité modérée).</li></ul>"},{"i":"3ea6f4e2ef5d","n":223,"o":"223-10","u":"Prise en charge","t":"Connaître les règles hygiéno-diététiques","q":"Comment doit être prise en charge une hypertriglycéridémie avec des triglycérides supérieurs à 30 g/L ?","a":"<p>Une hypertriglycéridémie supérieure à <strong>30 g/L</strong> est considérée comme une <strong>urgence nutritionnelle</strong>. Elle nécessite une <strong>diète hydrique transitoire</strong> jusqu'à la normalisation des triglycérides.</p>"},{"i":"40929e527681","n":223,"o":"223-10","u":"Prise en charge","t":"Connaître les règles hygiéno-diététiques","q":"Quelle est l'importance des règles hygiéno-diététiques (RHD) dans la prise en charge des dyslipidémies ?","a":"<p>Les règles hygiéno-diététiques constituent la <strong>première étape du traitement</strong> des dyslipidémies. Elles peuvent précéder, voire remplacer, un traitement médicamenteux.</p>"},{"i":"88268d508d56","n":223,"o":"223-10","u":"Prise en charge","t":"Connaître les règles hygiéno-diététiques","q":"Quelles sont les mesures hygiéno-diététiques essentielles pour un patient atteint d'hypertriglycéridémie ?","a":"<ul><li><strong>À favoriser :</strong> la réduction du surpoids (apports hypocaloriques -20 %) et la pratique d'une activité physique régulière.</li><li><strong>À limiter/éviter :</strong> l'alcool (avec un test d'éviction d'une semaine) et les sucres simples ainsi que les boissons sucrées.</li></ul>"},{"i":"a88fef29cfa5","n":223,"o":"223-10","u":"Prise en charge","t":"Connaître les règles hygiéno-diététiques","q":"Quelles sont les recommandations alimentaires spécifiques pour un patient atteint d'hypercholestérolémie ?","a":"<ul><li><strong>À favoriser :</strong> les fibres solubles (céréales complètes, légumineuses, fruits, légumes), les phytostérols et les acides gras insaturés (environ 15 % de l'apport calorique total).</li><li><strong>À limiter/éviter :</strong> les graisses totales (< 35 % de l'apport calorique), les acides gras saturés (< 10 %), les acides gras trans et la levure rouge de riz (à proscrire en raison d'effets indésirables similaires aux statines).</li></ul>"},{"i":"350cfbddf692","n":223,"o":"223-2","u":"Définition","t":"Connaître les trois grands types de dyslipidémies","q":"Quelle est l'anomalie lipidique caractéristique d'une hypercholestérolémie pure ?","a":"<p>L'hypercholestérolémie pure est caractérisée par une augmentation isolée du <strong>LDL-cholestérol</strong>.</p>"},{"i":"41e4d064a613","n":223,"o":"223-2","u":"Définition","t":"Connaître les trois grands types de dyslipidémies","q":"Comment l'aspect du sérum peut-il orienter vers le type de dyslipidémie ?","a":"<ul><li>Une hypercholestérolémie pure se manifeste par un sérum <strong>clair et limpide</strong>.</li><li>Une hypertriglycéridémie pure rend le sérum <strong>opalescent à lactescent</strong>.</li><li>Une hyperlipidémie mixte donne un sérum <strong>trouble</strong>.</li></ul>"},{"i":"5e6024c81b43","n":223,"o":"223-2","u":"Définition","t":"Connaître les trois grands types de dyslipidémies","q":"Quelle est l'anomalie lipidique caractéristique d'une hypertriglycéridémie pure ?","a":"<p>L'hypertriglycéridémie pure est caractérisée par une augmentation isolée des <strong>triglycérides</strong>.</p>"},{"i":"b66c06c56c0c","n":223,"o":"223-2","u":"Définition","t":"Connaître les trois grands types de dyslipidémies","q":"Quels sont les trois grands types de dyslipidémies de l'adulte et de l'enfant, basés sur l'anomalie lipidique dominante ?","a":"<p>Les trois grands types de dyslipidémies, selon l'anomalie lipidique dominante, sont :</p><ul><li>l'<strong>hypercholestérolémie pure</strong></li><li>l'<strong>hypertriglycéridémie pure</strong></li><li>l'<strong>hyperlipidémie mixte</strong></li></ul>"},{"i":"d80003380222","n":223,"o":"223-2","u":"Définition","t":"Connaître les trois grands types de dyslipidémies","q":"Quelle est l'anomalie lipidique caractéristique d'une hyperlipidémie mixte ?","a":"<p>L'hyperlipidémie mixte est caractérisée par une augmentation des <strong>LDL-cholestérol</strong> et des <strong>triglycérides</strong>.</p>"},{"i":"4f23509112d8","n":223,"o":"223-4","u":"Dépistage","t":"Savoir quand dépister une dyslipidémie ?","q":"Quand faut-il répéter un bilan lipidique de dépistage s'il est initialement normal chez un patient sans événement cardiovasculaire ni nouveau facteur de risque ?","a":"<p>Si le bilan lipidique est normal, en l'absence d'événement cardiovasculaire, de prise de poids ou de nouveau facteur de risque, il <strong>n'est pas justifié de le répéter avant 5 ans</strong>.</p>"},{"i":"4ff2c2f6b55e","n":223,"o":"223-4","u":"Dépistage","t":"Savoir quand dépister une dyslipidémie ?","q":"Quels sont les éléments cliniques et biologiques qui doivent faire suspecter une dyslipidémie primitive chez l'adulte et l'enfant ?","a":"<p>Une dyslipidémie primitive doit être suspectée devant :</p><ul><li>Une <strong>hypercholestérolémie familiale</strong> chez un parent.</li><li>Un <strong>LDL-c ≥ 1,9 g/L chez l'adulte</strong>, ou <strong>≥ 1,6 g/L chez l'enfant</strong>.</li><li>Une <strong>maladie cardiovasculaire athéromateuse précoce</strong> (personnelle ou familiale).</li><li>Des <strong>xanthomes tendineux</strong> ou un <strong>arc cornéen avant 45 ans</strong>.</li></ul>"},{"i":"d38cc7547938","n":223,"o":"223-4","u":"Dépistage","t":"Savoir quand dépister une dyslipidémie ?","q":"Dans quelles situations générales est indiqué un bilan lipidique de dépistage chez l'adulte et l'enfant ?","a":"<p>Un bilan lipidique de dépistage est indiqué dans les situations suivantes :</p><ul><li>Présence de <strong>facteurs de risque cardiovasculaire</strong> (pour l'estimation du risque cardiovasculaire absolu).</li><li><strong>Enquête familiale</strong> devant une dyslipidémie chez un apparenté.</li><li><strong>Pathologie associée</strong> ou <strong>prescription médicamenteuse</strong> pouvant induire une dyslipidémie secondaire.</li><li><strong>Contrôle systématique lié à l'âge</strong> (vers 50 ans chez l'homme, 60 ans chez la femme).</li></ul>"},{"i":"2d629402b1aa","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Comment calcule-t-on le LDL-cholestérol et dans quelle situation ce calcul est-il invalide ?","a":"<p>Le LDL-cholestérol est calculé par la <strong>formule de Friedewald</strong> :</p><ul><li>En g/L : <strong>LDL-C = CT − HDL-C − TG/5</strong></li><li>En mmol/L : <strong>LDL-C = CT − HDL-C − TG/2,2</strong></li></ul><p>Cette formule devient invalide si les <strong>triglycérides sont supérieurs à 3,4 g/L (3,9 mmol/L)</strong>, nécessitant alors un dosage direct du LDL-C.</p>"},{"i":"42dcb5081ac6","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Quelle est la principale complication d'une hypertriglycéridémie majeure et à partir de quel seuil devient-elle critique ?","a":"<p>Une hypertriglycéridémie majeure expose à la <strong>pancréatite aiguë</strong>. Ce risque est significatif dès que les triglycérides dépassent <strong>10 g/L</strong> et devient critique, constituant une urgence, au-delà de <strong>30 g/L</strong>.</p>"},{"i":"60a836a406f5","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Quels sont les seuils biologiques définissant une hypercholestérolémie et une hypertriglycéridémie ?","a":"<ul><li>Une <strong>hypercholestérolémie</strong> est définie par un <strong>LDL-C supérieur à 1,6 g/L</strong>.</li><li>Une <strong>hypertriglycéridémie</strong> est définie par des <strong>triglycérides supérieurs à 1,5 g/L</strong>.<br>Le HDL-C est considéré comme normal s'il est supérieur à 0,4 g/L.</li></ul>"},{"i":"6c870321f502","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Comment l'aspect du sérum lipidique et le test de crémage orientent-ils le diagnostic de dyslipidémie ?","a":"<p>Après 12h à 4°C :</p><ul><li><strong>Sérum clair</strong> : suggère une <strong>hypercholestérolémie</strong> pure (type IIa).</li><li><strong>Surnageant crémeux et sous-nageant clair</strong> : oriente vers une anomalie des <strong>chylomicrons</strong> (type I).</li><li><strong>Surnageant crémeux et sous-nageant trouble</strong> : indique une atteinte des <strong>chylomicrons et VLDL</strong> (type V).</li><li><strong>Sous-nageant trouble sans surnageant</strong> : suggère une anomalie des <strong>VLDL</strong> (type IV ou IIb).</li></ul>"},{"i":"854eed6df780","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Comment est réalisé le diagnostic biologique des dyslipidémies ?","a":"<p>Il repose sur une <strong>Exploration d'une Anomalie Lipidique (EAL)</strong>, réalisée après un <strong>jeûne de 12 heures</strong>. Elle comprend les dosages directs du :</p><ul><li><strong>Cholestérol total (CT)</strong></li><li><strong>Triglycérides (TG)</strong></li><li><strong>HDL-cholestérol (HDL-C)</strong></li></ul><p>Le <strong>LDL-cholestérol (LDL-C)</strong> est ensuite calculé, sauf si les triglycérides sont trop élevés.</p>"},{"i":"c4c1761e1f09","n":223,"o":"223-5","u":"Diagnostic positif","t":"Connaître le diagnostic positif et la classification des dyslipidémies","q":"Quels sont les différents types de dyslipidémies selon la classification de Fredrickson et leurs principales caractéristiques ?","a":"<ul><li><strong>Type I (hyperchylomicronémie familiale)</strong> : accumulation de <strong>chylomicrons</strong>, sérum lactescent (couche crémeuse), TG > 10 g/L, risque de <strong>pancréatite aiguë</strong>.</li><li><strong>Type IIa (hypercholestérolémie pure)</strong> : accumulation de <strong>LDL</strong>, sérum clair, LDL-C élevé, risque d'<strong>athérosclérose</strong>, xanthomes tendineux.</li><li><strong>Type IIb (hyperlipidémie mixte)</strong> : accumulation de <strong>LDL + VLDL</strong>, sérum opalescent, TG > 1,5 g/L et LDL-C élevé, risque d'<strong>athérosclérose</strong>.</li><li><strong>Type III (dysbêtalipoprotéinémie)</strong> : accumulation d'<strong>IDL</strong>, sérum opalescent, TG ≥ 1,5 g/L, <strong>xanthomes des plis palmaires (pathognomonique)</strong>.</li><li><strong>Type IV (hypertriglycéridémie)</strong> : accumulation de <strong>VLDL isolée</strong>, sérum trouble, TG ≥ 1,5 g/L.</li><li><strong>Type V (hyperchylomicronémie + hypertriglycéridémie)</strong> : accumulation de <strong>chylomicrons + VLDL</strong>, sérum opalescent (anneau crémeux), TG > 10 g/L, risque de <strong>pancréatite aiguë</strong>.</li></ul>"},{"i":"2367f41cdd81","n":223,"o":"223-6","u":"Contenu multimédia","t":"Connaître les manifestations cliniques des dyslipidémies : xanthelasma","q":"Quelle est la particularité sémiologique d'un xanthélasma dans le diagnostic des dyslipidémies ?","a":"<p>Le xanthélasma est <strong>évocateur</strong> d'une dyslipidémie (hypercholestérolémie), mais il n'est <strong>pas pathognomonique</strong>.</p>"},{"i":"549bb9870fea","n":223,"o":"223-6","u":"Contenu multimédia","t":"Connaître les manifestations cliniques des dyslipidémies : xanthelasma","q":"Quelle est la définition clinique d'un xanthélasma et à quelle affection est-il associé ?","a":"<p>Un xanthélasma est un dépôt lipidique extravasculaire caractérisé par des plaques de couleur <strong>jaune-orangé</strong>, localisées sur les paupières. Il est associé aux <strong>hypercholestérolémies</strong>.</p>"},{"i":"b421b7bc9b05","n":223,"o":"223-6","u":"Contenu multimédia","t":"Connaître les manifestations cliniques des dyslipidémies : xanthelasma","q":"À partir de quel âge un xanthélasma prend-il une valeur sémiologique significative pour une dyslipidémie ?","a":"<p>Un xanthélasma prend une valeur sémiologique significative lorsqu'il survient <strong>avant 60 ans</strong>.</p>"},{"i":"34c650238043","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quel est le principe de la prise en charge thérapeutique des hyperlipidémies secondaires ?","a":"<p>Les hyperlipidémies secondaires <strong>régressent avec le traitement étiologique</strong>. Il ne faut donc <strong>pas prescrire d'hypolipémiant</strong>, car cela est inutile, voire dangereux (ex: risque musculaire d'une statine en cas d'hypothyroïdie non corrigée).</p>"},{"i":"579665f1fa6d","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les causes iatrogènes spécifiques à l'hypercholestérolémie secondaire et à l'hyperlipidémie mixte secondaire ?","a":"<p>Les causes iatrogènes spécifiques sont :</p><ul><li>Les <strong>diurétiques thiazidiques</strong>.</li><li>Les <strong>immunosuppresseurs</strong> (<strong>ciclosporine</strong>, <strong>sirolimus</strong>, <strong>évérolimus</strong>).</li><li>Le <strong>bexarotène</strong>.</li></ul>"},{"i":"62a7496efbfd","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelle est l'exception concernant la régression de la dyslipidémie dans le cadre du diabète de type 2 (DT2) et du syndrome métabolique ?","a":"<p>La dyslipidémie associée au <strong>DT2</strong> et au <strong>syndrome métabolique</strong> ne régresse pas avec la seule normalisation glycémique. Celle-ci est <strong>liée à l'insulinorésistance</strong>.</p>"},{"i":"79fe7dac2482","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les causes communes d'hypercholestérolémie secondaire, d'hypertriglycéridémie secondaire et d'hyperlipidémie mixte secondaire ?","a":"<p>Les causes communes à ces trois types de dyslipidémies secondaires sont :</p><ul><li>La <strong>grossesse</strong>.</li><li>Le <strong>syndrome néphrotique</strong>.</li><li>L'<strong>hypothyroïdie</strong>.</li><li>Le <strong>déficit en GH</strong> (hormone de croissance).</li></ul>"},{"i":"80425b9c2880","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les étiologies non-iatrogènes spécifiques (hormis les causes communes) d'hypercholestérolémie secondaire ?","a":"<p>Les étiologies non-iatrogènes spécifiques d'hypercholestérolémie secondaire sont :</p><ul><li>La <strong>cholestase</strong>.</li><li>L'<strong>anorexie mentale</strong>.</li></ul>"},{"i":"d3f0aef99a59","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les causes iatrogènes spécifiques à l'hypertriglycéridémie secondaire ?","a":"<p>Parmi les causes iatrogènes d'hypertriglycéridémie secondaire, on retrouve :</p><ul><li>Les <strong>œstrogènes oraux</strong>.</li><li>Les <strong>bêta-bloquants</strong>.</li><li>L'<strong>interféron alpha</strong>.</li><li>Les <strong>antirétroviraux</strong>.</li></ul>"},{"i":"e6e115422e77","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les causes métaboliques spécifiques (hormis les causes communes) d'hypertriglycéridémie secondaire ?","a":"<p>Les causes métaboliques spécifiques d'hypertriglycéridémie secondaire sont :</p><ul><li>L'<strong>alcoolisme</strong>.</li><li>L'<strong>obésité</strong> et le <strong>syndrome métabolique</strong>.</li><li>L'<strong>acromégalie</strong>.</li><li>L'infection par le <strong>VIH</strong>.</li></ul>"},{"i":"f61cf6020b60","n":223,"o":"223-7","u":"Étiologies","t":"Connaître les principales causes d’hyperlipidémies secondaires","q":"Quelles sont les étiologies non-iatrogènes spécifiques (hormis les causes communes) de l'hyperlipidémie mixte secondaire ?","a":"<p>Les étiologies non-iatrogènes spécifiques de l'hyperlipidémie mixte secondaire sont :</p><ul><li>L'<strong>insuffisance rénale chronique</strong>.</li><li>Le <strong>diabète mal équilibré</strong>.</li><li>L'<strong>hypercorticisme</strong>.</li><li>Les <strong>antiprotéases</strong> (bien qu'il s'agisse alors de causes iatrogènes, elles sont listées ici comme spécifiques de l'hyperlipidémie mixte).</li><li>Les <strong>corticoïdes</strong>.</li><li>Les <strong>rétinoïdes</strong>.</li></ul>"},{"i":"180a205d4340","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quelle est la principale contre-indication médicamenteuse à connaître dans le traitement des dyslipidémies ?","a":"<p>L'association <strong>statine + gemfibrozil</strong> est formellement <strong>contre-indiquée</strong> en raison d'un risque élevé de <strong>rhabdomyolyse</strong>.</p>"},{"i":"1d7606b592ff","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Comment doit être surveillée l'atteinte musculaire lors d'un traitement par statine ?","a":"<p>La surveillance musculaire est avant tout <strong>clinique</strong>. Le dosage des <strong>CPK</strong> n'est recommandé qu'en cas de symptômes musculaires ou sur un terrain à risque.</p>"},{"i":"323e0d17f4f8","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quelle est la première étape dans la prise en charge d'une dyslipidémie secondaire ou iatrogène ?","a":"<p>La première étape est toujours de traiter la <strong>cause</strong> sous-jacente de la dyslipidémie, et non d'emblée un hypolipémiant.</p>"},{"i":"32ec5daf24cc","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quelle est la prise en charge d'une hypertriglycéridémie isolée ?","a":"<ul><li>Si triglycérides entre 1,5 et 5 g/L : <strong>diététique seule</strong>.</li><li>Si triglycérides &gt; 5 g/L : <strong>diététique</strong> puis <strong>fibrate</strong> (objectif &lt; 5 g/L pour prévenir la <strong>pancréatite</strong>), puis <strong>acides gras oméga-3</strong> en association.</li></ul>"},{"i":"4f6dd580351b","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quelle est la stratégie d'escalade thérapeutique pour une hypercholestérolémie isolée ?","a":"<ul><li><strong>1ʳᵉ intention</strong> : <strong>statine</strong>, débutée à faible posologie puis augmentée.</li><li>Si objectif non atteint : augmentation de dose ou statine plus puissante, puis <strong>ézétimibe</strong>, puis <strong>colestyramine</strong>.</li><li>En cas d'intolérance aux statines : <strong>ézétimibe</strong> voire <strong>colestyramine</strong>.</li><li>Les <strong>anti-PCSK9</strong> (alirocumab, évolocumab) sont réservés aux hypercholestérolémies familiales sévères, sur avis spécialisé.</li></ul>"},{"i":"53fb27cd8870","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quels sont le mécanisme d'action et les effets indésirables clés des statines ?","a":"<p>Les statines inhibent l'<strong>HMG-CoA-réductase</strong>, entraînant une diminution de 25 à 45 % du LDL-c. Les effets indésirables clés sont les <strong>myalgies</strong>, l'augmentation des <strong>CPK</strong> et des transaminases, ainsi qu'un surrisque de <strong>diabète de type 2</strong> (DT2).</p>"},{"i":"e3341e77e001","n":223,"o":"223-9","u":"Prise en charge","t":"Connaître les principes du traitement des dyslipidémies (voir item 330)","q":"Quelle est la stratégie thérapeutique pour une hyperlipidémie mixte ?","a":"<p>L'objectif prioritaire est le <strong>LDL-c</strong> (si triglycérides &lt; 5 g/L) avec une prise en charge associant <strong>diététique</strong> + <strong>statine</strong> ± <strong>ézétimibe</strong>. Un <strong>fénofibrate</strong> peut être ajouté en cas de haut risque cardiovasculaire avec triglycérides ≥ 2 g/L et HDL bas.</p>"}]};